text:
{
  "title": "استمارة طلب توظيف وإقرار معالجة البيانات الشخصية",
  "planted": [
    {
      "slot": "p1",
      "text": "نطلب تقارير الفحص الطبي الشامل والبيانات الجنائية حصرياً لتقييم الملاءمة المهنية للوظائف الحساسة، ولا نستخدم البيانات الحساسة إلا للأغراض التشغيلية المرتبطة بالوظيفة."
    },
    {
      "slot": "p2",
      "text": "نحتفظ بملفات المتقدمين وغير المقبولين في قواعد بياناتنا لفترات زمنية محددة بغرض الرجوع إليها في فرص التوظيف المستقبلية ما لم يطلب المتقدم خلاف ذلك."
    },
    {
      "slot": "p3",
      "text": "يقر المتقدم بموافقته على قيام الشركة بمعالجة بياناته واستخدامها لأغراض التوظيف المرتبطة بالشركة والشركات التابعة لها، مع جواز تعديل أو تحديث هذه الأغراض وفقاً لمتطلبات العمل الداخلية."
    }
  ],
  "neutral": [
    "يقصد بالطرف الأول في هذا النموذج شركة الأفق المتقدم المحدودة، ويقصد بالطرف الثاني المتقدم بطلب الوظيفة.",
    "تخضع كافة النزاعات الناشئة عن هذا المستند حصرياً للأنظمة المعمول بها في المملكة العربية السعودية.",
    "لا تتحمل الشركة أي مسؤولية مالية عن أية تكاليف يتكبدها المتقدم خلال مراحل تقديم الطلب أو المقابلات الشخصية.",
    "تعتبر هذه الاستمارة لاغية في حال عدم استكمال المتقدم للمستندات المطلوبة خلال مدة أقصاها سبعة أيام من تاريخ التقديم.",
    "تظل أحكام هذا المستند سارية المفعول طوال فترة دراسة الطلب وحتى إشعار آخر.",
    "تؤول ملكية كافة المواد والاختبارات المقدمة أثناء عملية التوظيف حصرياً للشركة.",
    "تتم كافة المراسلات الرسمية عبر البريد الإلكتروني المسجل في هذا الطلب وتعتبر نافذة بمجرد إرسالها.",
    "لا يترتب على تقديم هذا الطلب أي التزام قانوني على الشركة بتوظيف المتقدم."
  ]
}
